package dev.mikaaah.tnkloot.compat;

import com.google.gson.*;
import dev.mikaaah.tnkloot.TnkLoot;
import java.io.InputStreamReader;
import java.nio.charset.StandardCharsets;
import java.nio.file.*;
import java.util.*;
import net.neoforged.fml.loading.FMLPaths;

/** The TNK pack's existing removals also apply to equipment generated by this mod. */
public final class PackItemPolicy {
    private PackItemPolicy() {}
    private static volatile Set<String> disabled;
    public static Set<String> disabled() {
        if (disabled == null) reload();
        return disabled;
    }
    public static boolean allowed(String id) { return !disabled().contains(id); }
    public static synchronized boolean reload() {
        try {
            Path catalog = FMLPaths.GAMEDIR.get().resolve("kubejs/pack_catalog.json");
            JsonObject root;
            if (Files.exists(catalog)) {
                try (var reader = Files.newBufferedReader(catalog)) { root = JsonParser.parseReader(reader).getAsJsonObject(); }
            } else {
                try (var stream = PackItemPolicy.class.getResourceAsStream("/tnk-pack-item-policy.json")) {
                    if (stream == null) throw new IllegalStateException("Missing TNK item policy");
                    root = JsonParser.parseReader(new InputStreamReader(stream, StandardCharsets.UTF_8)).getAsJsonObject();
                }
            }
            disabled = parse(root); return true;
        } catch (Exception error) {
            TnkLoot.LOG.error("Invalid TNK pack item policy; retaining the last valid exclusions", error);
            if (disabled == null) {
                try (var stream = PackItemPolicy.class.getResourceAsStream("/tnk-pack-item-policy.json")) {
                    if (stream == null) throw new IllegalStateException("Missing TNK item policy");
                    disabled = parse(JsonParser.parseReader(new InputStreamReader(stream, StandardCharsets.UTF_8)).getAsJsonObject());
                } catch (Exception missing) { throw new IllegalStateException("Cannot load the bundled TNK item policy", missing); }
            }
            return false;
        }
    }
    private static Set<String> parse(JsonObject root) {
        Set<String> next = new HashSet<>();
        for (String field : List.of("fullyDisabledItems", "infiniteFoods")) {
            if (!root.has(field) || !root.get(field).isJsonArray()) throw new IllegalArgumentException("Missing item policy: " + field);
            for (var value : root.getAsJsonArray(field)) {
                String id = value.getAsString();
                if (net.minecraft.resources.ResourceLocation.tryParse(id) == null) throw new IllegalArgumentException("Invalid policy item: " + id);
                next.add(id);
            }
        }
        return Set.copyOf(next);
    }

}
